const C=window.TETRO_PUZZLE_CATALOG,A={ATK:'#ff6b7d',DEF:'#5ba8ff',HP:'#2ee6a6',EVAS:'#c287ff',ACC:'#ffbe55',CRIT_RES:'#6fe3ff',CRIT:'#ff76cf'},L={ATK:'攻擊',DEF:'防禦',HP:'生命',EVAS:'迴避',ACC:'命中',CRIT_RES:'爆擊抵抗',CRIT:'爆擊'},ORDER=['ATK','DEF','HP','CRIT','ACC','EVAS','CRIT_RES'];
const D=[
 {id:'O',name:'O · 攻擊',cells:[[0,0],[1,0],[0,1],[1,1]],attr:'ATK'},
 {id:'I',name:'I · 防禦',cells:[[0,0],[0,1],[0,2],[0,3]],attr:'DEF'},
 {id:'T',name:'T · 生命',cells:[[0,0],[1,0],[2,0],[1,1]],attr:'HP'},
 {id:'L',name:'L · 迴避',cells:[[0,0],[0,1],[0,2],[1,2]],attr:'EVAS'},
 {id:'J',name:'J · 命中',cells:[[1,0],[1,1],[0,2],[1,2]],attr:'ACC'},
 {id:'S',name:'S · 爆擊抵抗',cells:[[1,0],[2,0],[0,1],[1,1]],attr:'CRIT_RES'},
 {id:'Z',name:'Z · 爆擊',cells:[[0,0],[1,0],[1,1],[2,1]],attr:'CRIT'}
],$=s=>document.querySelector(s);
let puzzles=[...C.puzzles,...loadCustom()],N=9,mask=[],solutions=[],solutionKeys=new Set(),selected=0,running=false,nodes=0,edit=false,sortPriority=[...ORDER],customSort=false,activeLimits=null;
function norm(c){let x=Math.min(...c.map(v=>v[0])),y=Math.min(...c.map(v=>v[1]));return c.map(([a,b])=>[a-x,b-y]).sort((a,b)=>a[1]-b[1]||a[0]-b[0])}
function variants(c){let out=new Map;for(let r=0;r<4;r++){let v=c.map(([x,y])=>{for(let i=0;i<r;i++)[x,y]=[-y,x];return[x,y]});v=norm(v);out.set(JSON.stringify(v),v)}return[...out.values()]}
D.forEach(d=>d.variants=variants(d.cells));
function loadCustom(){try{let v=JSON.parse(localStorage.getItem('tetroCustomPuzzles')||'[]');return Array.isArray(v)?v:[]}catch{return[]}}
function saveCustom(){localStorage.setItem('tetroCustomPuzzles',JSON.stringify(puzzles.filter(p=>p.custom)))}
function options(){$('#puzzle').innerHTML=puzzles.map((p,i)=>`<option value="${i}">${String(i+1).padStart(2,'0')} · ${p.name_zh}${p.custom?'（自訂）':''}</option>`).join('')}
function loadPuzzle(i=Number($('#puzzle').value)||0){let p=puzzles[i];N=9;mask=p.rows.join('').split('').map(x=>x==='1');solutions=[];selected=nodes=0;$('#puzzle').value=i;$('#puzzleName').textContent=p.name_zh;$('#puzzleMeta').textContent=`${p.name_ko||'自訂'} · ${p.active_cells} 格 · ${i+1}/${puzzles.length}`;board();stats();results();$('#status').textContent='選擇排序需求後按「開始計算」'}
function renderLimits(){$('#limits').innerHTML='<div class="limit-row limit-head"><span>能力</span><span>最低</span><span>最高</span></div>'+ORDER.map(a=>`<label class="limit-row"><span>${L[a]}</span><input data-attr="${a}" data-bound="min" type="number" min="0" max="20" value="0" aria-label="${L[a]}最低數量"><input data-attr="${a}" data-bound="max" type="number" min="0" max="20" placeholder="不限" aria-label="${L[a]}最高數量"></label>`).join('')+'<p class="sort-note mode-help">固定數量時，最低與最高輸入相同數字；最高留白代表不限。</p>'}
function readLimits(){if($('#mode').value!=='advanced')return null;let limits={};ORDER.forEach(a=>{let min=Number($(`#limits input[data-attr="${a}"][data-bound="min"]`).value)||0,raw=$(`#limits input[data-attr="${a}"][data-bound="max"]`).value;limits[a]={min,max:raw===''?Infinity:Math.max(0,Number(raw)||0)}});return limits}
function meetsLimits(counts){return !activeLimits||ORDER.every(a=>{let n=counts[a]||0,v=activeLimits[a];return n>=v.min&&n<=v.max})}
function board(layout){let b=$('#board');b.style.gridTemplateColumns='repeat(9,1fr)';b.innerHTML='';let color={};if(layout)layout.placements.forEach((p,i)=>p.cells.forEach(k=>color[k]={c:A[p.attr],i}));mask.forEach((on,i)=>{let c=document.createElement('button');c.className='cell '+(on?'':'off')+(color[i]?' filled':'');c.ariaLabel='棋盤格 '+(i+1);if(color[i]){c.style.background=color[i].c;c.title=layout.placements[color[i].i].name}else c.onclick=()=>{if(edit&&!running){mask[i]=!mask[i];solutions=[];board();stats();results()}};b.append(c)});$('#boardMeta').textContent=layout?`${layout.placements.length} 塊 · ${ORDER.filter(a=>layout.counts[a]).map(a=>`${L[a]} ${layout.counts[a]}`).join(' · ')}`:(edit?'自訂模式：點擊格子編輯':'已載入謎題棋盤')}
function stats(){$('#activeCount').textContent=mask.filter(Boolean).length;$('#solutionCount').textContent=solutions.length.toLocaleString();$('#nodeCount').textContent=nodes.toLocaleString()}
function renderSort(){document.querySelectorAll('#sortOptions button[data-attr]').forEach(b=>{let i=sortPriority.indexOf(b.dataset.attr);b.classList.toggle('selected',i>=0);b.querySelector('b').textContent=i>=0?i+1:'＋'})}
function pickSort(attr){if(!customSort){sortPriority=[attr];customSort=true}else{let i=sortPriority.indexOf(attr);if(i>=0)sortPriority.splice(i,1);else sortPriority.push(attr)}renderSort();selected=0;results()}
function sortKeys(){return sortPriority}
function compareSolutions(a,b,keys=sortKeys()){for(let k of keys){let d=(b.counts[k]||0)-(a.counts[k]||0);if(d)return d}return 0}
function results(){let h=$('#results');if(!solutions.length){h.innerHTML='<div class="empty">結果會顯示在這裡</div>';$('#layoutNo').textContent='尚未計算';board();return}solutions.sort((a,b)=>compareSolutions(a,b));selected=Math.min(selected,solutions.length-1);h.innerHTML='';solutions.slice(0,200).forEach((s,i)=>{let q=document.createElement('button');q.className='result '+(i===selected?'active':'');q.innerHTML=`<strong>方案 ${i+1}</strong><div class="chips">${ORDER.filter(a=>s.counts[a]).map(a=>`<span class="chip" style="border-left:3px solid ${A[a]}">${L[a]} × ${s.counts[a]}</span>`).join('')}</div>`;q.onclick=()=>{selected=i;board(s);results()};h.append(q)});board(solutions[selected]);$('#layoutNo').textContent=`${selected+1} / ${solutions.length}`}
function placeAt(target,filled,used){let y=Math.floor(target/N),x=target%N,out=[],rank=new Map(sortKeys().map((a,i)=>[a,i]));D.forEach((d,di)=>{if(activeLimits&&used[di]>=activeLimits[d.attr].max)return;d.variants.forEach(v=>v.forEach(a=>{let ox=x-a[0],oy=y-a[1],cells=[],ok=true;for(let [dx,dy]of v){let xx=ox+dx,yy=oy+dy,k=yy*N+xx;if(xx<0||yy<0||xx>=N||yy>=N||!mask[k]||filled[k]){ok=false;break}cells.push(k)}if(ok)out.push({di,cells,name:d.name,attr:d.attr})}))});return out.sort((a,b)=>(rank.get(a.attr)??99)-(rank.get(b.attr)??99))}
function solutionKey(counts){return ORDER.map(a=>counts[a]||0).join(',')}
function keepSolution(s){if(!meetsLimits(s.counts))return;let signature=solutionKey(s.counts);if(solutionKeys.has(signature))return;let keys=sortKeys();if(solutions.length<2000){solutions.push(s);solutionKeys.add(signature);if(solutions.length===2000)solutions.sort((a,b)=>compareSolutions(a,b,keys));return}if(compareSolutions(s,solutions[solutions.length-1],keys)>=0)return;let removed=solutions.pop();solutionKeys.delete(solutionKey(removed.counts));let lo=0,hi=solutions.length;while(lo<hi){let mid=(lo+hi)>>1;if(compareSolutions(s,solutions[mid],keys)<0)hi=mid;else lo=mid+1}solutions.splice(lo,0,s);solutionKeys.add(signature)}
async function solve(){if(running){running=false;return}let active=mask.filter(Boolean).length;if(!active||active%4){$('#status').textContent='棋盤有效格數必須是 4 的倍數';return}running=true;solutions=[];solutionKeys.clear();nodes=selected=0;$('#solve').textContent='停止';$('#status').textContent='依優先級搜尋最佳方案…';let filled=Array(81).fill(false),used=Array(7).fill(0),stack=[],last=0,limited=false;async function dfs(n){if(!running||nodes>=1500000){limited=true;return}nodes++;if(nodes-last>4000){last=nodes;stats();$('#bar').style.width=Math.min(96,nodes/15000)+'%';await new Promise(r=>setTimeout(r,0))}if(n===active){let counts={};stack.forEach(p=>counts[p.attr]=(counts[p.attr]||0)+1);keepSolution({placements:stack.map(p=>({...p,cells:[...p.cells]})),counts});return}let best=null;for(let k=0;k<81;k++)if(mask[k]&&!filled[k]){let ps=placeAt(k,filled,used);if(!ps.length)return;if(!best||ps.length<best.length){best=ps;if(ps.length===1)break}}for(let p of best){p.cells.forEach(k=>filled[k]=true);used[p.di]++;stack.push(p);await dfs(n+4);stack.pop();used[p.di]--;p.cells.forEach(k=>filled[k]=false);if(!running||nodes>=1500000)return}}await dfs(0);running=false;$('#solve').textContent='開始計算';$('#bar').style.width='100%';stats();results();$('#status').textContent=solutions.length?(limited?'已達搜尋安全上限，顯示目前最佳結果':'最佳方案搜尋完成'):'找不到完整排列'}
function savePuzzle(){let name=prompt('自訂謎題名稱');if(!name)return;let rows=[];for(let y=0;y<9;y++)rows.push(mask.slice(y*9,y*9+9).map(Number).join(''));let p={id:'custom_'+Date.now(),index:puzzles.length,name_ko:'',name_zh:name,width:9,height:9,rows,active_cells:mask.filter(Boolean).length,custom:true};puzzles.push(p);saveCustom();options();$('#puzzle').value=puzzles.length-1;loadPuzzle(puzzles.length-1)}
function exportPuzzles(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({schema_version:1,puzzles:puzzles.filter(p=>p.custom)},null,2)],{type:'application/json'}));a.download='tetro-custom-puzzles.json';a.click();URL.revokeObjectURL(a.href)}
$('#puzzle').onchange=()=>loadPuzzle();$('#solve').onclick=solve;$('#sortOptions').onclick=e=>{let b=e.target.closest('button[data-attr]');if(b)pickSort(b.dataset.attr)};$('#clearSort').onclick=()=>{sortPriority=[];customSort=true;renderSort();selected=0;results()};$('#defaultSort').onclick=()=>{sortPriority=[...ORDER];customSort=false;renderSort();selected=0;results()};$('#editBoard').onclick=()=>{edit=!edit;$('#editBoard').textContent=edit?'完成編輯':'自訂棋盤';board()};$('#reset').onclick=()=>{sortPriority=[...ORDER];customSort=false;renderSort();loadPuzzle()};$('#savePuzzle').onclick=savePuzzle;$('#exportPuzzles').onclick=exportPuzzles;options();renderSort();loadPuzzle(0);
renderLimits();$('#mode').onchange=()=>{let advanced=$('#mode').value==='advanced';$('#limits').hidden=!advanced;activeLimits=readLimits();solutions=[];solutionKeys.clear();selected=0;stats();results();$('#status').textContent=advanced?'設定最低／最高數量後開始計算':'依能力優先順序快速找出最佳方案'};$('#limits').oninput=()=>activeLimits=readLimits();$('#reset').addEventListener('click',()=>{renderLimits();$('#mode').value='quick';$('#limits').hidden=true;activeLimits=null});
